 1	package dedupe
 2	
 3	import (
 4		"sort"
 5		"strings"
 6		"time"
 7	)
 8	
 9	// Event is one normalized audit-log record.
10	type Event struct {
11		TS     time.Time
12		Actor  string
13		Action string
14		Target string
15		Hash   string
16	}
17	
18	// Run removes exact duplicates and near-duplicates that fall within window.
19	func Run(events []Event, window time.Duration) []Event {
20		out := make([]Event, 0, len(events))
21		for i := range events {
22			dup := false
23			for j := range out {
24				if sameEvent(events[i], out[j]) && absDur(events[i].TS.Sub(out[j].TS)) <= window {
25					dup = true
26					break
27				}
28			}
29			if !dup {
30				out = append(out, events[i])
31			}
32		}
33		return out
34	}
35	
36	func sameEvent(a, b Event) bool {
37		return a.Actor == b.Actor && a.Action == b.Action &&
38			a.Target == b.Target && strings.EqualFold(a.Hash, b.Hash)
39	}
40	
41	func absDur(d time.Duration) time.Duration {
42		if d < 0 {
43			return -d
44		}
45		return d
46	}
47	
48	// SortByTS orders events oldest-first; used by the CLI before writing output.
49	func SortByTS(events []Event) {
50		sort.SliceStable(events, func(i, j int) bool { return events[i].TS.Before(events[j].TS) })
51	}

