// Run removes exact duplicates and near-duplicates that fall within window.
//
// Events are visited in timestamp order over a sliding window: a candidate is only
// checked against the keys still inside the window, and keys are evicted once they
// fall more than window behind the current event. That replaces the quadratic scan
// over every kept event. Output is restored to input order.
func Run(events []Event, window time.Duration) []Event {
	if len(events) < 2 {
		return append([]Event(nil), events...)
	}

	order := make([]int, len(events))
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool {
		return events[order[a]].TS.Before(events[order[b]].TS)
	})

	keep := make([]int, 0, len(events))
	live := make(map[string]time.Time, 1024)
	left := 0
	for _, idx := range order {
		cur := events[idx]
		for left < len(keep) {
			old := events[keep[left]]
			if cur.TS.Sub(old.TS) <= window {
				break
			}
			if ts, ok := live[eventKey(old)]; ok && ts.Equal(old.TS) {
				delete(live, eventKey(old))
			}
			left++
		}
		if _, dup := live[eventKey(cur)]; dup {
			continue
		}
		live[eventKey(cur)] = cur.TS
		keep = append(keep, idx)
	}

	sort.Ints(keep)
	out := make([]Event, 0, len(keep))
	for _, idx := range keep {
		out = append(out, events[idx])
	}
	return out
}

// eventKey mirrors sameEvent: the hash comparison stays case-insensitive.
func eventKey(e Event) string {
	return e.Actor + "\x00" + e.Action + "\x00" + e.Target + "\x00" + strings.ToLower(e.Hash)
}

